  stroke(255);
  strokeWeight(6);
  for (let i = slashVisuals.length - 1; i >= 0; i--) {
    let v = slashVisuals[i];
    line(v.x1, v.y1, v.x2, v.y2);
    v.timer--;
    if (v.timer <= 0) slashVisuals.splice(i, 1);
  }
  noStroke();

  // Simple HUD for lives
  fill(255, 0, 128);
  for (let i = 0; i < lives; i++) {
    rect(10 + i * 15, 30, 10, 10);
  }
}

// ============================================================
// HELPERS
// ============================================================

function rectIntersect(r1, r2) {
  // r1: center x,y + w,h
  // r2: top-left x,y + w,h
  let r1L = r1.x - r1.w/2;
  let r1R = r1.x + r1.w/2;
  let r1T = r1.y - r1.h/2;
  let r1B = r1.y + r1.h/2;

  let r2L = r2.x;
  let r2R = r2.x + r2.w;
  let r2T = r2.y;
  let r2B = r2.y + r2.h;

  return !(r2L > r1R || r2R < r1L || r2T > r1B || r2B < r1T);
}

function pointInRect(px, py, r2) {
  return (px >= r2.x && px <= r2.x + r2.w && py >= r2.y && py <= r2.y + r2.h);
}
